def sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def write_complete(path: Path, source: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(source.lstrip(), encoding="utf-8", newline="\n")
    ast.parse(path.read_text(encoding="utf-8"), filename=str(path))
    print(f"[OK] FULL REPLACEMENT: {path.resolve()}")


def protected_sources() -> dict[Path, str]:
    result = {}
    prefixes = (
        ROOT / "qseries_v2" / "oracle_intelligence" / "live_acquisition",
        ROOT / "qseries_v2" / "oracle_intelligence" / "analytics",
        ROOT / "qseries_v2" / "oracle_intelligence_integration",
        ROOT / "qseries_v2" / "oracle_research_runtime",
        ROOT / "qseries_v2" / "oracle_operator_runtime",
        ROOT / "qseries_v2" / "qseries",
    )
    for base in prefixes:
        if base.exists():
            for path in base.rglob("*.py"):
                if path.is_file():
                    result[path] = sha256(path)
    for path in (OIT_007, RUNNER):
        if path.is_file():
            result[path] = sha256(path)
    return result


def main() -> int:
    print("=" * 40)
    print(" OIT-008 CORRECTION V3 INSTALLER")
    print(" FULL QUERY EXECUTION REPLACEMENT")
    print("=" * 40)
    try:
        if not OIT_007.is_file():
            raise RuntimeError(f"Actual OIT-007 module missing: {OIT_007}")
        if not RUNNER.is_file():
            raise RuntimeError(f"Actual terminal runner missing: {RUNNER}")

        oit_007_text = OIT_007.read_text(encoding="utf-8")
        required = (
            'SCHEMA_VERSION = "OIT-007"',
            "build_queryable_intelligence_read_model",
            "verify_queryable_intelligence_read_model",
            "record_hash",
            "searchable_text",
        )
        missing = [item for item in required if item not in oit_007_text]
        if missing:
            raise RuntimeError(f"OIT-007 contract incomplete: {missing}")

        protected = protected_sources()
        print("[OK] Actual OIT-007 queryable read model verified")
        print("[OK] Current terminal runner captured and preserved")
        print(f"[OK] Protected production source files captured: {len(protected)}")

        write_complete(PRODUCTION, PRODUCTION_SOURCE)
        write_complete(TEST, TEST_SOURCE)

        export = (
            "from .oracle_natural_language_query_planning_and_execution import *"
        )
        current = INIT.read_text(encoding="utf-8") if INIT.exists() else ""
        if export not in current.splitlines():
            if current and not current.endswith("\n"):
                current += "\n"
            INIT.write_text(
                current + export + "\n",
                encoding="utf-8",
                newline="\n",
            )
            print(f"[OK] PACKAGE UPDATED: {INIT.resolve()}")
        else:
            print(f"[OK] PACKAGE EXPORT PRESENT: {INIT.resolve()}")
        ast.parse(INIT.read_text(encoding="utf-8"), filename=str(INIT))

        completed = subprocess.run(
            [sys.executable, str(TEST)],
            cwd=ROOT,
            check=False,
        )
        if completed.returncode:
            raise RuntimeError(
                f"OIT-008 CORRECTION V3 test failed with exit code "
                f"{completed.returncode}"
            )

        for path, expected in protected.items():
            if not path.is_file() or sha256(path) != expected:
                raise RuntimeError(
                    f"Protected production source changed: {path}"
                )

        print("[PASS] OIT-007 production module unchanged")
        print("[PASS] Current terminal runner unchanged")
        print("[PASS] OLA, OIA, INT-OII, ORR, OOR, and Q Series unchanged")
        print("[PASS] Entire OIT-008 production module replaced")
        print("[PASS] Entire OIT-008 test replaced")
        print("[PASS] Required content-term enforcement certified")
        print("[PASS] Generic schema-only query support certified")
        print("[PASS] Complete production test passed")
        print(f"[PASS] Repository located: {ROOT}")
        print("[DONE] OIT-008 CORRECTION V3 FULL REPLACEMENT INSTALLED")
        return 0
    except (RuntimeError, SyntaxError) as exc:
        print(f"[ERROR] {exc}")
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
